INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Müssen alle Datenverarbeitungen laut DSGVO einen Zweck haben?', 2, '[{"text": "Ja", "correct": true, "because": "Zweckbindung ist ein Grundsatz"}, {"text": "Nein", "correct": false, "because": "Ohne Zweck ist es unrechtmäßig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip steht im Mittelpunkt der Datenminimierung?', 3, '[{"text": "Nur nötige Daten erheben", "correct": true, "because": "Reduziert Risiken"}, {"text": "Maximale Datenspeicherung", "correct": false, "because": "Widerspricht dem Grundsatz"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Grundsätze gehören zur DSGVO?', 5, '[{"text": "Rechtmäßigkeit", "correct": true, "because": "Verarbeitung muss legal sein"}, {"text": "Transparenz", "correct": true, "because": "Nutzer müssen informiert werden"}, {"text": "Hohe Performance", "correct": false, "because": "Kein Datenschutzprinzip"}, {"text": "Maximale Speicherung", "correct": false, "because": "Widerspricht Minimierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Zweckbindung erfordert einen klaren Verarbeitungszweck. b) Datenminimierung ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Minimierung ist verpflichtend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Umsetzung von Datenschutzgrundsätzen?', 4, '[{"text": "Einwilligung der Nutzer", "correct": false, "because": "Kern der Rechtmäßigkeit"}, {"text": "Datenlöschfristen", "correct": false, "because": "Teil der Speicherbegrenzung"}, {"text": "Designpräferenzen", "correct": true, "because": "Nicht datenschutzrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Rechtmäßigkeit ohne Einwilligung möglich ist?', 2, '[{"text": "Ja", "correct": true, "because": "Andere Rechtsgrundlagen existieren"}, {"text": "Nein", "correct": false, "because": "Einwilligung ist nur eine Option"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Grundsatz sorgt dafür, dass Nutzer informiert werden?', 3, '[{"text": "Transparenz", "correct": true, "because": "Verpflichtet zu klarer Kommunikation"}, {"text": "Integrität", "correct": false, "because": "Bezieht sich auf Daten"}, {"text": "Verfügbarkeit", "correct": false, "because": "Kein DSGVO-Grundsatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prinzipien schützen personenbezogene Daten?', 5, '[{"text": "Datenminimierung", "correct": true, "because": "Begrenzt erhobene Daten"}, {"text": "Zweckbindung", "correct": true, "because": "Beschränkt Nutzung"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Schutzprinzip"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Irrelevant für Schutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Datenminimierung reduziert Risiken. b) Zweckbindung ist nur für große Firmen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Zweckbindung gilt für alle"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Einhaltung der DSGVO-Grundsätze?', 4, '[{"text": "Rechtsgrundlage", "correct": false, "because": "Kern der Rechtmäßigkeit"}, {"text": "Dokumentation", "correct": false, "because": "Nachweis erforderlich"}, {"text": "Maximale Datensammlung", "correct": true, "because": "Widerspricht Minimierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Datenminimierung nur für sensible Daten?', 2, '[{"text": "Nein", "correct": true, "because": "Gilt für alle Daten"}, {"text": "Ja", "correct": false, "because": "Universelles Prinzip"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen unterstützen die Zweckbindung?', 4, '[{"text": "Klar definierte Zwecke", "correct": true, "because": "Begrenzt Verwendung"}, {"text": "Nutzerinformation", "correct": true, "because": "Fördert Transparenz"}, {"text": "Unbegrenzte Speicherung", "correct": false, "because": "Widerspricht DSGVO"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Rechtmäßigkeit automatisch erfüllt ist. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Braucht aktive Umsetzung"}, {"text": "Ja", "correct": false, "because": "Erfordert Grundlage"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Datenminimierung?', 3, '[{"text": "Nur nötige Daten erheben", "correct": true, "because": "Reduziert Risiken"}, {"text": "Maximale Datenspeicherung", "correct": false, "because": "Widerspricht Prinzip"}, {"text": "Schnelle Verarbeitung", "correct": false, "because": "Sekundär"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Transparenz erfordert klare Kommunikation. b) Datenminimierung erlaubt alles zu speichern.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Minimierung schränkt ein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Grundsätze fördern den Datenschutz?', 5, '[{"text": "Rechtmäßigkeit", "correct": true, "because": "Sichert legale Basis"}, {"text": "Speicherbegrenzung", "correct": true, "because": "Begrenzt Datenhaltung"}, {"text": "Hohe Verfügbarkeit", "correct": false, "because": "Kein DSGVO-Prinzip"}, {"text": "Maximale Erhebung", "correct": false, "because": "Widerspricht Minimierung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Zweckbindung unwichtig?', 3, '[{"text": "Klarer Zweck", "correct": false, "because": "Kern des Prinzips"}, {"text": "Nutzerzustimmung", "correct": false, "because": "Teil der Rechtmäßigkeit"}, {"text": "UI-Design", "correct": true, "because": "Kein Datenschutzfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal mit der Rechtmäßigkeit? Ist sie immer einwilligungsbasiert?', 3, '[{"text": "Nein", "correct": true, "because": "Verträge oder Gesetze zählen auch"}, {"text": "Ja", "correct": false, "because": "Mehrere Grundlagen möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Datenminimierung Speicherfristen betrifft?', 2, '[{"text": "Nein", "correct": true, "because": "Das ist Speicherbegrenzung"}, {"text": "Ja", "correct": false, "because": "Minimierung ist Erhebung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip wähle ich, um Daten nur für einen Zweck zu nutzen?', 4, '[{"text": "Zweckbindung", "correct": true, "because": "Beschränkt Verwendung"}, {"text": "Maximale Speicherung", "correct": false, "because": "Widerspricht DSGVO"}, {"text": "Hohe Verfügbarkeit", "correct": false, "because": "Kein Schutzprinzip"}]');
